const CACHE='mech-battle-1.1.0';
const FILES=['./','./index.html','./styles.css?v=1.1.0','./icon.svg','./manifest.webmanifest','./icons/apple-touch-icon.png','./icons/icon-192.png','./icons/icon-512.png','./src/main.js?v=1.1.0','./src/parts.js?v=1.1.0','./src/simulation.js?v=1.1.0','./src/state.js?v=1.1.0','./src/renderer.js?v=1.1.0','./src/software-renderer.js?v=1.1.0','./src/audio.js?v=1.1.0','./src/build-analysis.js?v=1.1.0','./src/ui-components.js?v=1.1.0','./src/mech-detail.js?v=1.1.0','./src/mesh-batch.js?v=1.1.0','./vendor/three.module.min.js','./vendor/three.core.min.js'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('mech-battle-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(c=>c.put(event.request,copy));}return response;}).catch(()=>caches.match(event.request).then(cached=>cached||event.request.mode==='navigate'&&caches.match('./index.html')||Response.error())));});
